function process(items: any[]) {
  // TODO: handle empty arrays
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    total += items[i].amount;
  }
  return total;
}

export function legacyCharge(items: any[]) {
  if (!items) return 0;
  let sum = 0;
  items.forEach(i => { sum += i.cost * i.qty; });
  return sum;
}

// Version A
function total(items: { quantity: number; price: number }[]) {
  if (!items || items.length === 0) return 0;
  return items.reduce((s, i) => s + i.quantity * i.price, 0);
}

